import copy


def deep_merge(base, override):
    """Layer `override` over `base`.

    Returns a new dict. Neither argument is changed at any depth, and the
    result shares no dict or list object with either argument at any depth.
    """
    result = {}

    # Keys of base in their order.
    for key in base:
        if key in override:
            ov = override[key]
            # A key whose value in override is None is removed from the result.
            if ov is None:
                continue
            if isinstance(ov, dict) and isinstance(base[key], dict):
                result[key] = deep_merge(base[key], ov)
            else:
                result[key] = copy.deepcopy(ov)
        else:
            result[key] = copy.deepcopy(base[key])

    # New keys of override in their order.
    for key in override:
        if key in base:
            continue
        ov = override[key]
        # If the key is not in base, a None value does nothing.
        if ov is None:
            continue
        result[key] = copy.deepcopy(ov)

    return result
